    private void btnLoginActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLoginActionPerformed
       String username = txtUsername.getText();
    String password = new String(txtPassword.getPassword());

    try {
        Connection conn = DBConnection.connect();

        // Check Admin table first
        String sqlAdmin = "SELECT * FROM admin WHERE username=? AND password=?";
        PreparedStatement pstAdmin = conn.prepareStatement(sqlAdmin);
        pstAdmin.setString(1, username);
        pstAdmin.setString(2, password);
        ResultSet rsAdmin = pstAdmin.executeQuery();

        if (rsAdmin.next()) {
            JOptionPane.showMessageDialog(this, "Welcome Admin!");
            new Dashboard().setVisible(true);
            this.dispose();
        } else {
            // If not found in admin, check staff
            String sqlStaff = "SELECT * FROM staff WHERE username=? AND password=?";
            PreparedStatement pstStaff = conn.prepareStatement(sqlStaff);
            pstStaff.setString(1, username);
            pstStaff.setString(2, password);
            ResultSet rsStaff = pstStaff.executeQuery();

            if (rsStaff.next()) {
                JOptionPane.showMessageDialog(this, "Welcome Staff!");
                new StaffDashboard().setVisible(true);
                this.dispose();
            } else {
                JOptionPane.showMessageDialog(this, "Invalid Username or Password");
            }
        }

        conn.close();
    } catch (Exception e) {
        JOptionPane.showMessageDialog(this, "Error: " + e.getMessage());
    }
    }//GEN-LAST:event_btnLoginActionPerformed

